fn remove_duplicates(nums: &Vec<i32>) -> usize {
    let n = nums.len();
    if n == 0 {
        return 0;
    }

    let mut distinct: usize = 1;
    for i in 1..n {
        if nums[i] != nums[i - 1] {
            distinct += 1;
        }
    }
    distinct
}

fn main() {
    // Basic sanity checks
    assert_eq!(remove_duplicates(&vec![]), 0);
    assert_eq!(remove_duplicates(&vec![1]), 1);
    assert_eq!(remove_duplicates(&vec![1, 1, 1]), 1);
    assert_eq!(remove_duplicates(&vec![1, 1, 2, 2, 3]), 3);
    assert_eq!(remove_duplicates(&vec![-2, -2, -1, 0, 0, 5]), 4);
}